definition.script:
pipeline {
  agent any

  options {
    timestamps()
    buildDiscarder(logRotator(numToKeepStr: '15'))
    timeout(time: 60, unit: 'MINUTES')
    disableConcurrentBuilds()
  }

  parameters {
    string(name: 'IMAGE_TAG', defaultValue: 'latest',
           description: 'Image tag to pull from the registry: latest, or a specific git short sha.')
  }

  environment {
    REGISTRY = 'localhost:5001'
    SLUG = 'johndoe6345789/metabuilder'
  }

  stages {
    stage('Checkout') {
      steps {
        git branch: 'main', url: 'https://github.com/johndoe6345789/metabuilder.git'
      }
    }

    stage('Docker Preflight') {
      steps {
        sh '''
          docker version
          docker compose version
          curl -fsS -I http://localhost:5001/v2/ || true
        '''
      }
    }

    // metabuilder-apps pushes app images to ${REGISTRY}/${SLUG}/<name>. The
    // compose stack (deployment/metabuilder/compose.yml, project "deployment")
    // expects them as local deployment-<svc>:latest tags. Pull + retag so
    // `stack up` reuses them instead of rebuilding. Best-effort per image: a
    // missing image just means its service will not start.
    stage('Hydrate App Images From Registry') {
      steps {
        script {
          def defs = readJSON file: 'deployment/cli/commands.json'
          def apps = defs.definitions.nexus_images.apps
          if (defs.definitions.nexus_images.heavy_apps) {
            apps += defs.definitions.nexus_images.heavy_apps
          }
          def missing = []
          for (img in apps) {
            def src = "${env.REGISTRY}/${env.SLUG}/${img.name}:${params.IMAGE_TAG}"
            def rc = sh(script: "docker pull ${src}", returnStatus: true)
            if (rc != 0) {
              missing.add(src)
              continue
            }
            sh "docker tag ${src} ${img.local}"
            sh "docker rmi -f ${src} || true"
            echo "Hydrated ${img.local} from ${src}"
          }
          if (!missing.isEmpty()) {
            echo "WARNING: ${missing.size()} app image(s) not in the registry; their services may not start:"
            for (m in missing) { echo "  - ${m}" }
          }
        }
      }
    }

    stage('Deploy Stack') {
      steps {
        sh '''
          set -e
          cd deployment
          python3 deployment.py stack up
        '''
      }
    }

    stage('Status') {
      steps {
        sh '''
          cd deployment
          python3 deployment.py stack ps || true
        '''
      }
    }
  }

  post {
    success {
      echo 'metabuilder stack deployed - portal: http://localhost:8900'
    }
    always {
      cleanWs()
    }
  }
}
